#pragma once

constexpr char productionDiagnosticsPageJapanese[] = R"HTML(
<!doctype html><html lang="ja"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>水上ボート 診断</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#f4f5f7;color:#18202a;font:16px system-ui,sans-serif}main{max-width:760px;margin:auto;padding:18px}h1{font-size:23px;margin:4px 0 12px}.panel{background:#fff;border:1px solid #d7dce2;border-radius:10px;padding:13px;margin:12px 0}.title{font-weight:800;margin-bottom:9px}.summary{border-radius:9px;padding:12px;font-weight:750;background:#f2f5f8;line-height:1.55}.summary.ok{background:#dcf3e3}.summary.bad{background:#fde0df}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}.item{border-radius:8px;padding:9px;background:#f2f5f8;min-height:65px}.item.ok{background:#dcf3e3}.item.bad{background:#fde0df}.key{font-size:12px;font-weight:750;color:#59636e}.value{font-weight:800;overflow-wrap:anywhere;margin-top:3px}.detail{font-size:13px;line-height:1.55;color:#59636e;margin-top:5px}.list{margin:0;padding-left:20px;line-height:1.65}.events{display:grid;gap:7px}.event{border-left:4px solid #8796a5;background:#f2f5f8;padding:8px 9px;border-radius:0 7px 7px 0;line-height:1.45}.age{font-size:12px;color:#59636e;font-weight:700}.hint{color:#59636e;font-size:13px;line-height:1.55}@media(max-width:520px){.grid{grid-template-columns:1fr}}
</style><main>
<div style="text-align:right"><a href="/" style="color:#1859a8;font-weight:700">← 制御画面へ</a>　<a href="/track" style="color:#1859a8;font-weight:700">航跡</a>　<a href="/sensors" style="color:#1859a8;font-weight:700">センサー</a></div><h1>通信・機器診断</h1>
<div id="summary" class="summary">通信側XIAOから診断情報を取得しています…</div>
<section class="panel"><div class="title">制御側XIAOとのUARTリンク</div><div id="link" class="grid"></div><div id="link-detail" class="detail"></div></section>
<section class="panel"><div class="title">通信側XIAO</div><div id="communication" class="grid"></div></section>
<section class="panel"><div class="title">制御側・接続機器</div><div id="control" class="grid"></div></section>
<section class="panel"><div class="title">現在の開始阻害要因</div><ul id="blockers" class="list"></ul><div class="hint">表示中の制御選択に対する条件です。ウェイポイントのみではBNO08Xは必須ではありません。</div></section>
<section class="panel"><div class="title">直近イベント（再起動で消去）</div><div id="events" class="events"></div></section>
<div class="hint">3秒ごとに更新します。診断ページは読み取り専用で、制御指令は送りません。</div>
</main><script>
const $=id=>document.getElementById(id);const yes=v=>v?'OK':'未認識';const age=v=>v===4294967295||v==null?'未受信':(Number(v)<1000?Number(v)+' ms':(Number(v)/1000).toFixed(1)+' 秒');
function cell(k,v,ok,detail=''){return '<div class="item '+(ok?'ok':'bad')+'"><div class="key">'+k+'</div><div class="value">'+v+'</div>'+(detail?'<div class="detail">'+detail+'</div>':'')+'</div>'}
function render(d){const l=d.link,c=d.communication,x=d.control,o=d.operation;const good=l.connected;$('summary').className='summary '+(good?'ok':'bad');$('summary').textContent=good?'制御側XIAOとのUART通信は受信中です。':'制御側XIAOとのUART通信を受信できていません。下の理由を確認してください。';$('link').innerHTML=cell('リンク',good?'接続中':'未接続',good,'最終受信: '+age(l.age_ms))+cell('受信フレーム',l.frames,Number(l.frames)>0,'起動後の累計')+cell('CRC エラー',l.crc_errors,Number(l.crc_errors)===0)+cell('COBS / 長さエラー',l.cobs_errors+' / '+l.length_errors,Number(l.cobs_errors)===0&&Number(l.length_errors)===0);$('link-detail').textContent=l.diagnosis;$('communication').innerHTML=cell('GNSS測位',yes(c.gnss_valid),c.gnss_valid,'最終更新: '+age(c.gnss_age_ms)+' / 衛星 '+c.satellites)+cell('GNSS受信文 / チェックサム',c.sentences+' / '+c.checksum_errors,Number(c.checksum_errors)===0)+cell('SDカード',yes(c.sd_ready),c.sd_ready,c.logging?'記録中':'記録停止中')+cell('Web接続端末',c.wifi_clients+' 台',true,'通信側 稼働 '+(Number(d.uptime_ms)/60000).toFixed(1)+' 分');$('control').innerHTML=cell('制御側スナップショット',yes(x.snapshot),x.snapshot,'最終: '+age(x.snapshot_age_ms))+cell('安全状態',x.safety_name,x.safety_name==='DISARMED'||x.safety_name==='RUNNING','停止理由: '+x.stop_reason_name)+cell('PCA9685',yes(x.pca),x.pca)+cell('BNO08X',yes(x.imu),x.imu,'姿勢制御ON時のみ必須')+cell('制御側GNSS',yes(x.gnss),x.gnss)+cell('VESC電源 / テレメトリ',yes(x.power)+' / '+yes(x.vesc),x.power&&x.vesc)+cell('ToF',yes(x.tof),x.tof,'高さ補正用・任意')+cell('現在の操作',o.stage,true,(o.waypoint?'ウェイポイント ':'')+(o.attitude?'姿勢制御':'姿勢制御なし'));
 $('blockers').innerHTML=(d.blockers||[]).map(v=>'<li>'+v+'</li>').join('')||'<li>なし</li>';$('events').innerHTML=(d.events||[]).length?d.events.slice().reverse().map(e=>'<div class="event"><div class="age">'+age(e.age_ms)+' 前</div>'+e.text+'</div>').join(''):'イベントはまだありません。'}
async function load(){try{const r=await fetch('/api/diagnostics',{cache:'no-store'});if(!r.ok)throw Error();render(await r.json())}catch(e){$('summary').className='summary bad';$('summary').textContent='通信側XIAOから診断情報を取得できません。'}}setInterval(load,3000);load();
</script></html>)HTML";
